package dustin.cex.domains.valuation;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.domains.security.AuditService;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

/** 방법별 새 DB에서 가격 원본/실패·현재 위치·감사·잠금을 검증한다. 실제 가격 공급사/금융 원장 호출은 없다. */
@SpringBootTest
@ActiveProfiles("test")
@EnabledIfEnvironmentVariable(named="CEX_TEST_DATABASE_URL",matches="jdbc:postgresql:.+")
class BitcoinKrwPriceIntegrationTest {
    @DynamicPropertySource static void settings(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("CEX_TEST_DATABASE_URL"));r.add("spring.datasource.driver-class-name",()->"org.postgresql.Driver");r.add("spring.datasource.username",()->"root");r.add("spring.datasource.password",()->"1234");r.add("spring.jpa.properties.hibernate.dialect",()->"org.hibernate.dialect.PostgreSQLDialect");r.add("spring.jpa.hibernate.ddl-auto",()->"create-drop");r.add("customer-mail.dispatch-enabled",()->false);for(String key:List.of("rpc-url","rpc-user","rpc-password","wallet"))r.add("bitcoin."+key,()->"");}
    @MockitoBean dustin.cex.shared.http.EngineHttpClient engine;
    @MockitoBean dustin.cex.shared.kafka.KafkaEventProducer producer;
    @MockitoBean dustin.cex.domains.fee.service.FeeConfigService fees;
    @MockitoBean dustin.cex.domains.kyc.DiditClient didit;
    @MockitoBean BitcoinKrwPriceClient client;
    @Autowired JdbcTemplate jdbc;
    @Autowired PlatformTransactionManager manager;
    @Autowired ObjectMapper json;
    @Autowired AuditService audit;
    BitcoinKrwPriceService service;
    @BeforeEach void isolated(){assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_attempts",Long.class));service=new BitcoinKrwPriceService(true,client,jdbc,audit,manager);when(client.read()).thenAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return quote(Instant.now());});}
    @AfterEach void noFinancialDelivery(){verifyNoInteractions(engine,producer);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM user_balances",Long.class));}
    BitcoinKrwPriceClient.Quote quote(Instant read){Instant provider=Instant.ofEpochMilli(read.toEpochMilli()),trade=provider.minusMillis(10);BigDecimal price=new BigDecimal("123456789.12345678");String payload=json.writeValueAsString(List.of(Map.of("market","KRW-BTC","trade_price",price,"trade_timestamp",trade.toEpochMilli(),"timestamp",provider.toEpochMilli())));try{return new BitcoinKrwPriceClient.Quote(price,trade,provider,read,read,payload,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload.getBytes(StandardCharsets.UTF_8))));}catch(GeneralSecurityException failure){throw new IllegalStateException(failure);}}
    void unavailable(Runnable action){assertEquals(503,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
    AuditService failing(String action){var failed=mock(AuditService.class);doAnswer(call->{if(action.equals(call.getArgument(1)))throw new IllegalStateException("격리 가격 감사 실패");audit.record(call.getArgument(0),call.getArgument(1),call.getArgument(2),call.getArgument(3),call.getArgument(4));return null;}).when(failed).record(any(),anyString(),anyString(),anyString(),anyString());return failed;}
    @Test void committedStartPrecedesIoAndPendingHeadCannotExposeOlderQuote(){var old=service.refresh();when(client.read()).thenAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_attempts",Long.class));unavailable(service::current);return quote(Instant.now());});var next=service.refresh();assertNotEquals(old.attemptId(),next.attemptId());var current=service.current();assertEquals(next.attemptId(),current.attemptId());assertEquals(new BigDecimal("123456789.12345678"),current.price());assertEquals(4,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE target='btc-krw-reference'",Long.class));}
    @Test void latestProviderAndInternalFailuresNeverBorrowOldSuccessfulQuote(){service.refresh();when(client.read()).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.BAD_GATEWAY,"공급사 민감 원문"));assertEquals("PROVIDER_UNAVAILABLE",service.refresh().failureCode());unavailable(service::current);doThrow(new IllegalStateException("내부 민감 원문")).when(client).read();assertEquals("INTERNAL_FAILURE",service.refresh().failureCode());unavailable(service::current);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_results WHERE payload IS NOT NULL",Long.class));assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_results",Long.class));}
    @Test void disabledAndAmbientCallsCannotStartAnySourceIo(){var disabled=new BitcoinKrwPriceService(false,client,jdbc,audit,manager);unavailable(disabled::refresh);unavailable(disabled::current);assertDoesNotThrow(()->new TransactionTemplate(manager).execute(t->{unavailable(service::current);return 1;}));assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(t->service.refresh()));verifyNoInteractions(client);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_attempts",Long.class));}
    @Test void startAuditFailureRollsBackBeforeProviderIo(){var failed=new BitcoinKrwPriceService(true,client,jdbc,failing("BTC_KRW_PRICE_STARTED"),manager);assertThrows(IllegalStateException.class,failed::refresh);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_attempts",Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_heads",Long.class));verifyNoInteractions(client);}
    @Test void finishAuditFailureLeavesPendingHeadInsteadOfInventingProviderFailure(){var old=service.refresh();var failed=new BitcoinKrwPriceService(true,client,jdbc,failing("BTC_KRW_PRICE_FINISHED"),manager);assertThrows(IllegalStateException.class,failed::refresh);unavailable(service::current);assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_attempts",Long.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_results",Long.class));assertEquals(old.attemptId(),jdbc.queryForObject("SELECT attempt_id FROM btc_krw_price_results",Long.class));}
    @Test void concurrentRefreshHasOneClaimAndNoSecondSourceCall()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(client.read()).thenAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return quote(Instant.now());});try(var pool=Executors.newFixedThreadPool(2)){var running=pool.submit(service::refresh);assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(409,assertThrows(ResponseStatusException.class,service::refresh).getStatusCode().value());release.countDown();assertEquals("SUCCESS",running.get(10,TimeUnit.SECONDS).status());}finally{release.countDown();}verify(client,times(1)).read();}
    @Test void sourceRowsAreImmutableAndHeadCannotBeRewound(){var first=service.refresh();var second=service.refresh();for(String table:List.of("btc_krw_price_attempts","btc_krw_price_results"))for(String prefix:List.of("DELETE FROM ","TRUNCATE "))assertThrows(DataAccessException.class,()->jdbc.execute(prefix+table));assertThrows(DataAccessException.class,()->jdbc.update("UPDATE btc_krw_price_heads SET attempt_id=? WHERE singleton=true",first.attemptId()));assertEquals(second.attemptId(),service.current().attemptId());}
    @Test void sqlCannotStoreIncompleteOrMismatchedQuote(){when(client.read()).thenAnswer(call->{long id=jdbc.queryForObject("SELECT attempt_id FROM btc_krw_price_heads",Long.class);var missing=assertThrows(DataAccessException.class,()->jdbc.update("INSERT INTO btc_krw_price_results(attempt_id,status) VALUES(?,'SUCCESS')",id));assertEquals("23514",((java.sql.SQLException)missing.getMostSpecificCause()).getSQLState());var q=quote(Instant.now());var altered=assertThrows(DataAccessException.class,()->jdbc.update("INSERT INTO btc_krw_price_results(attempt_id,status,price,trade_at,provider_at,read_started_at,read_finished_at,payload,payload_hash) VALUES(?,'SUCCESS',?,?,?,?,?,?,?)",id,q.price(),Timestamp.from(q.tradeAt()),Timestamp.from(q.providerAt()),Timestamp.from(q.readStartedAt()),Timestamp.from(q.readFinishedAt()),q.payload(),"0".repeat(64)));assertEquals("23514",((java.sql.SQLException)altered.getMostSpecificCause()).getSQLState());return q;});assertEquals("SUCCESS",service.refresh().status());}
    @Test void callerTransactionPinsCurrentHeadUntilItFinishes()throws Exception{var original=service.refresh();clearInvocations(client);var reading=new CountDownLatch(1);var release=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var reader=pool.submit(()->new TransactionTemplate(manager).execute(t->{var value=service.current();reading.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException failure){throw new IllegalStateException(failure);}return value;}));assertTrue(reading.await(5,TimeUnit.SECONDS));var writer=pool.submit(service::refresh);org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(3)).until(()->jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%btc_krw_price_heads%')",Boolean.class));verifyNoInteractions(client);release.countDown();assertEquals(original.attemptId(),reader.get(10,TimeUnit.SECONDS).attemptId());assertNotEquals(original.attemptId(),writer.get(10,TimeUnit.SECONDS).attemptId());}finally{release.countDown();}}
    @Test void staleHistoricalQuoteIsNotCurrentAndRemainsUnchanged(){var old=quote(Instant.now().minusSeconds(181));new TransactionTemplate(manager).executeWithoutResult(t->{long id=jdbc.queryForObject("INSERT INTO btc_krw_price_attempts(started_at) VALUES(?) RETURNING id",Long.class,Timestamp.from(old.readStartedAt()));jdbc.update("INSERT INTO btc_krw_price_heads(singleton,attempt_id) VALUES(true,?)",id);jdbc.update("INSERT INTO btc_krw_price_results(attempt_id,status,price,trade_at,provider_at,read_started_at,read_finished_at,payload,payload_hash) VALUES(?,'SUCCESS',?,?,?,?,?,?,?)",id,old.price(),Timestamp.from(old.tradeAt()),Timestamp.from(old.providerAt()),Timestamp.from(old.readStartedAt()),Timestamp.from(old.readFinishedAt()),old.payload(),old.payloadHash());});unavailable(service::current);verifyNoInteractions(client);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_results WHERE status='SUCCESS'",Long.class));}
    @Test void ownedProductionPublisherCapturesSourceAndStops(){try(var context=new org.springframework.context.annotation.AnnotationConfigApplicationContext()){context.getEnvironment().setActiveProfiles("production");context.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("격리 공개 참고가격",Map.of("valuation.upbit.enabled","true")));context.registerBean("bitcoinKrwPriceSchemaInitializer",Object.class,Object::new);context.registerBean(BitcoinKrwPriceService.class,()->service);context.register(BitcoinKrwPriceWorker.class);context.refresh();org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(4)).untilAsserted(()->assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM btc_krw_price_results WHERE status='SUCCESS'",Long.class)));}verify(client,times(1)).read();assertEquals(new BigDecimal("123456789.12345678"),service.current().price());}

}
